{"implementation": "def solve(case):
    payload = case.get('payload')
    if not payload:
        raise ValueError('missing payload')
    segments = payload.get('segments')
    budget = payload.get('budget')
    if not isinstance(segments, list) or not isinstance(budget, int):
        raise ValueError('invalid payload structure')
    sum_min = sum(s['minimum'] for s in segments)
    sum_cap = sum(s['capacity'] for s in segments)
    if budget < sum_min or budget > sum_cap:
        raise ValueError('budget out of feasible range')
    alloc = {s['name']: s['minimum'] for s in segments}
    remaining = budget - sum_min
    n = len(segments)
    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i, s in enumerate(segments):
            name = s['name']
            current = alloc[name]
            if current >= s['capacity']:
                continue
            score = s['importance'] / (current + 1)
            if score > best_score or (score == best_score and (best_idx == -1 or i < best_idx)):
                best_score = score
                best_idx = i
        if best_idx == -1:
            break
        name = segments[best_idx]['name']
        alloc[name] += 1
        remaining -= 1
    result = {
        'allocations': alloc,
        'names': [s['name'] for s in segments],
        'total': sum(alloc.values())
    }
    return result
"}
